using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class PerimeterPolish {
 public static object ImportVital(){string p="Assets/Afrer_Seconds/05.Model/Props/B5/";AssetDatabase.ImportAsset(p+"CP_VitalMonitor_Repaired.fbx",ImportAssetOptions.ForceSynchronousImport);var im=(ModelImporter)AssetImporter.GetAtPath(p+"CP_VitalMonitor_Repaired.fbx");foreach(string n in new[]{"Coat","Steel","Dark","Blue","Screen","Trace","Paper","Rubber"})im.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"CP_"+n),AssetDatabase.LoadAssetAtPath<Material>(p+"Materials/CP_"+n+".mat"));im.SaveAndReimport();var s=SceneManager.GetActiveScene();var t=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>()).Single(x=>x.name=="CP_VitalMonitor_Repaired");var lod=t.GetComponent<LODGroup>();var rs=t.GetComponentsInChildren<Renderer>();lod.SetLODs(new[]{new LOD(.25f,new[]{rs.Single(r=>r.name.EndsWith("LOD0"))}),new LOD(.10f,new[]{rs.Single(r=>r.name.EndsWith("LOD1"))}),new LOD(.02f,new[]{rs.Single(r=>r.name.EndsWith("LOD2"))})});lod.RecalculateBounds();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{lods=rs.Length};}
 static Vector3 Polar(float a,float r,float y=0)=>new Vector3(Mathf.Cos(a*Mathf.Deg2Rad)*r,y,Mathf.Sin(a*Mathf.Deg2Rad)*r);
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit scene required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var room=root.Find("C01_Experiment_Art");var bank=room.Find("C01_Perimeter_Lab");var retired=room.Find("Retired_C01_SparseFixtures");
  int narrow=0;foreach(Transform bay in bank){if(!bay.name.StartsWith("Station_"))continue;foreach(Transform model in bay)if(new[]{"CP_LabBench","CP_DrawerBench","CP_WashBench"}.Contains(model.name)){model.localScale=new Vector3(.92f,1,1);PrefabUtility.RecordPrefabInstancePropertyModifications(model);narrow++;}}
  var old=root.Find("Existing_Props_FirstPass/B5-07_P13");if(old){old.SetParent(retired,true);old.name="B5-07_P13_Previous";}
  var back=root.GetComponentsInChildren<Transform>().Single(t=>t.name=="CD-029_CFD_ServiceBackplate");back.position=room.position+Polar(152,9.30f,.99f);PrefabUtility.RecordPrefabInstancePropertyModifications(back);
  var vital=room.Find("S1_VitalMonitor_18");vital.position=room.position+Polar(244,7.4f);PrefabUtility.RecordPrefabInstancePropertyModifications(vital);
  var cart=root.Find("Existing_Props_FirstPass/B5-06_P09");cart.position=room.position+Polar(294,7.5f);PrefabUtility.RecordPrefabInstancePropertyModifications(cart);
  foreach(var lamp in bank.Find("Integrated_Worklights").GetComponentsInChildren<Light>()){int a=int.Parse(lamp.name.Split('_').Last());lamp.intensity=3.2f;lamp.spotAngle=120;lamp.innerSpotAngle=70;lamp.transform.LookAt(room.position+Polar(a,8.65f,.92f));}
  Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{narrow,retiredOriginalCabinet=true,vitalRadius=7.4,diagnosticCartRadius=7.5};
 }
 public static object ImportUpdated(){var logs=new System.Collections.Generic.List<string>();Application.LogCallback cb=(m,s,t)=>{if(t==LogType.Warning||t==LogType.Error||t==LogType.Exception)logs.Add(t+": "+m);};Application.logMessageReceived+=cb;try{foreach(var name in new[]{"CP_EmergencyCabinet","CP_PerimeterServiceRuns"})AssetDatabase.ImportAsset("Assets/Afrer_Seconds/05.Model/Props/B5/"+name+".fbx",ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);return new{logs};}finally{Application.logMessageReceived-=cb;}}
}
